import{z as d,x as p,o as i,c as A,q as E,j as r,D as t,d as s,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"缓存雪崩与热键","description":"","frontmatter":{"title":"缓存雪崩与热键","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cache-stampede-hotkey.md","filePath":"cs/cache-stampede-hotkey.md","lastUpdated":1791063341000}'),m={name:"cs/cache-stampede-hotkey.md"};function B(T,a,h,c,D,u){const l=p("Mermaid");return i(),A("div",null,[a[2]||(a[2]=E('<h1 id="缓存雪崩与热键" tabindex="-1">缓存雪崩与热键 <a class="header-anchor" href="#缓存雪崩与热键" aria-label="Permalink to &quot;缓存雪崩与热键&quot;">​</a></h1><div class="epigraph"><p>大批键同时过期，或单键被打到一台存储，miss 路径把后端打穿。要错开 TTL、单飞填充、并对热键分片或本地层。</p><footer>—— 据 Nishtala et al., Scaling Memcache at Facebook, NSDI 2013；业界 stampede / dogpile 实践整理</footer></div><p>上一课<a href="/cs/distributed-cache-invalidation">缓存失效</a>的 miss 会打存储。缺口是<strong>miss 同步到来</strong>：雪崩是时间对齐，热键是空间对齐。本课钉缓解，不重写版本 cas。后课限流是更外层的保护，缓存打穿时限流是后备。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>雪崩：同一时刻大量 TTL 到期或重启空缓存，所有读变 miss。热键：流行键的 QPS 超过单存储分片。单飞（singleflight）：同一键并发 miss 只允许一个填充，其余等——租约在 Facebook memcache 里就是这种锁。没有单飞，N 个应用进程 × M 个 worker 对同一 miss 放大成 N×M 次查询。</p><p>缺口：只加机器不加错开与单飞，重启仍是雪崩。只加缓存不加热键分片，单键仍打穿。</p><p><span class="marginnote">dogpile/stampede 是同一现象的两个名字。逻辑时钟课的租约在这里变成填充租约，期限很短。</span></p><p><span class="marginnote">术语翻译：单飞（singleflight）就是用「同一键只放行一个查询」的手段来做「保护存储」的事——100 个请求同时 miss 时，只有 1 个去查库并回填，其余 99 个原地等它把结果带回来，而不是各自去敲存储的门。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TTL 加抖动，避免对齐。预热关键键。分层：进程内缓存挡热键，再分布式缓存，再库。热键拆成多个子键随机读（若语义允许）或复制到多缓存节点。降级：打穿时返回旧值（若还留着 stale-if-error）。</p>',10)),(i(),r(n,null,{default:t(()=>[o(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MISS%5B%22%E5%B9%B6%E5%8F%91%20miss%22%5D%20--%3E%20SF%5B%22%E5%8D%95%E9%A3%9E%20%2F%20%E5%A1%AB%E5%85%85%E7%A7%9F%E7%BA%A6%22%5D%0A%20%20SF%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%E6%89%93%E5%AD%98%E5%82%A8%22%5D%0A%20%20TTL%5B%22TTL%20%2B%20%E6%8A%96%E5%8A%A8%22%5D%20--%3E%20SPREAD%5B%22%E9%94%99%E5%BC%80%E8%BF%87%E6%9C%9F%22%5D%0A%20%20HOT%5B%22%E7%83%AD%E9%94%AE%22%5D%20--%3E%20L1%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%20%2F%20%E5%88%86%E7%89%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要用全局锁「填充全世界」。锁本身会雪崩。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：10000 个键都写着 3600 秒 TTL，过期点在同一秒，那一瞬间就是 10000 个 miss。若写入时各加 0–60 秒随机抖动，过期就摊成每秒约 167 个，存储瞬时压力降两个数量级——这正是「抖动要写在填充时」的原因。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,[s("与"),e("a",{href:"/cs/failure-detectors"},"故障检测"),s("：存储变慢使填充超时，重试放大，形成活锁。熔断下一课。缓存空窗与发布同时发生（滚动升级后课）是雪崩常见组合。")],-1)),a[7]||(a[7]=e("p",null,"本课不把 CDN 流量工程写全。也不写 GPU 热键。",-1)),a[8]||(a[8]=e("p",null,"过期对齐常来自「午夜批任务写同一 TTL」。抖动必须在写填充时做，不是只在配置里写一个常数。",-1)),(i(),r(n,null,{default:t(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLOW%5B%22%E5%AD%98%E5%82%A8%E5%8F%98%E6%85%A2%22%5D%20--%3E%20TO%5B%22%E5%A1%AB%E5%85%85%E8%AF%B7%E6%B1%82%E8%B6%85%E6%97%B6%22%5D%0A%20%20TO%20--%3E%20RETRY%5B%22%E8%B0%83%E7%94%A8%E6%96%B9%E9%87%8D%E8%AF%95%E5%90%8C%E4%B8%80%20miss%22%5D%0A%20%20RETRY%20--%3E%20MORE%5B%22%E5%B9%B6%E5%8F%91%E6%9F%A5%E8%AF%A2%E7%BF%BB%E5%80%8D%22%5D%0A%20%20MORE%20--%3E%20SLOW%0A%20%20GUARD%5B%22%E5%8D%95%E9%A3%9E%20%2B%20%E9%80%80%E9%81%BF%20%2B%20%E6%97%A7%E5%80%BC%E5%85%9C%E5%BA%95%22%5D%20-.-%3E%7C%22%E5%88%87%E6%96%AD%E5%BE%AA%E7%8E%AF%22%7C%20MORE%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=E('<p><span class="marginnote">常见误区：热键靠「再加几台缓存机」解决不了——一个键按哈希只会落在一台分片上，加机器不改变这一台承受的 QPS。出路要么是拆成多个子键随机读，要么在每个应用进程的本地内存里各放一份副本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给容量规划公式。后课默认：缓存层必须有单飞与 TTL 抖动；热键有本地层或拆分。限流熔断接在打穿之后当保险丝，不是第一道。超时退避再下一课把重试放大钉死。</p><p>同步 miss 是负载峰值的制造器。缓存的命中率曲线在过期点不连续。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>雪崩：过期/变空对齐；用抖动与预热。</li><li>热键：单飞 + 本地层或拆分。</li><li>填充租约防止 miss 放大。</li><li>出处：Nishtala et al., NSDI 2013；stampede 实践。</li></ul>',6))])}const g=d(m,[["render",B]]);export{S as __pageData,g as default};
